1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	
5	const COMPONENT_BASE_PREMIUM = 25;
6	const BLOCK_SIZE = 3;
7	const BLOCK_PREMIUM = 60;
8	
9	const BASE_PREMIUM: Record<string, number> = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: COMPONENT_BASE_PREMIUM,
15	  moonstone: COMPONENT_BASE_PREMIUM,
16	};
17	
18	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
19	
20	type Item = { type: string; cursed?: boolean };
21	type Scenario = {
22	  customer: { yearsWithMHPCO: number };
23	  steps: Array<{ op: "quote"; items: Item[] }>;
24	};
25	
26	const countsByType = (items: Item[]): Map<string, number> =>
27	  items.reduce(
28	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
29	    new Map<string, number>(),
30	  );
31	
32	const groupBase = (type: string, count: number): number =>
33	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
34	    ? BLOCK_PREMIUM
35	    : count * BASE_PREMIUM[type];
36	
37	const itemsBase = (items: Item[]): number => {
38	  let total = 0;
39	  for (const [type, count] of countsByType(items)) {
40	    total += groupBase(type, count);
41	  }
42	  return total;
43	};
44	
45	const itemSurcharge = (item: Item): number => {
46	  const base = BASE_PREMIUM[item.type];
47	  return item.cursed ? base * CURSE_SURCHARGE_RATE : 0;
48	};
49	
50	const itemSurchargesTotal = (items: Item[]): number =>
51	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
52	
53	const roundUpInFavorOfInsurer = (amount: number): number =>
54	  Math.ceil(Math.round(amount * 1e6) / 1e6);
55	
56	const quotePremium = (items: Item[]): number => {
57	  const policyBase = itemsBase(items);
58	  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
59	  const surcharges = itemSurchargesTotal(items);
60	  return roundUpInFavorOfInsurer(policyBase + surcharges + firstInsurance + PROCESSING_FEE);
61	};
62	
63	export const runScenario = (scenario: unknown): unknown => ({
64	  results: (scenario as Scenario).steps.map((step) => ({
65	    premium: quotePremium(step.items),
66	  })),
67	});
